def count_up(n):
    for i in range(1, n + 1):
        yield i

for num in count_up(5):
    print(num)

def fibonacci():
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b

for _, n in zip(range(8), fibonacci()):
    print(n)

def read_lines(text):
    for line in text.split('\n'):
        yield line.strip()

poem = '''  roses are red
  violets are blue
generators are lazy  '''

for line in read_lines(poem):
    print(line)

